BEGIN TRANSACTION;
CREATE TABLE current_findings (
                    asset_id TEXT NOT NULL,
                    cve_id TEXT NOT NULL,
                    first_seen TEXT NOT NULL,
                    last_seen TEXT NOT NULL,
                    fingerprint TEXT NOT NULL,
                    payload_json TEXT NOT NULL,
                    PRIMARY KEY(asset_id, cve_id)
                );
CREATE TABLE deliveries (
                    event_id INTEGER NOT NULL REFERENCES events(event_id),
                    channel TEXT NOT NULL,
                    state TEXT NOT NULL CHECK(state IN ('pending','accepted','failed')),
                    attempts INTEGER NOT NULL DEFAULT 0,
                    updated_at TEXT NOT NULL,
                    error TEXT,
                    PRIMARY KEY(event_id, channel)
                );
CREATE TABLE events (
                    event_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    run_id TEXT NOT NULL REFERENCES runs(run_id),
                    occurred_at TEXT NOT NULL,
                    asset_id TEXT NOT NULL,
                    cve_id TEXT NOT NULL,
                    event_type TEXT NOT NULL CHECK(event_type IN ('new','changed')),
                    fingerprint TEXT NOT NULL,
                    payload_json TEXT NOT NULL
                );
CREATE TABLE runs (
                    run_id TEXT PRIMARY KEY,
                    started_at TEXT NOT NULL,
                    completed_at TEXT NOT NULL,
                    status TEXT NOT NULL CHECK(status IN ('completed','failed')),
                    asset_count INTEGER NOT NULL,
                    finding_count INTEGER NOT NULL,
                    coverage_unknown_count INTEGER NOT NULL
                );
CREATE TABLE scan_assets (
                    run_id TEXT NOT NULL REFERENCES runs(run_id),
                    asset_id TEXT NOT NULL,
                    payload_json TEXT NOT NULL,
                    PRIMARY KEY(run_id, asset_id)
                );
CREATE TABLE scan_attempts (
                    attempt_id TEXT PRIMARY KEY,
                    started_at TEXT NOT NULL,
                    completed_at TEXT,
                    status TEXT NOT NULL CHECK(status IN ('running','completed','failed')),
                    run_id TEXT REFERENCES runs(run_id),
                    message TEXT NOT NULL
                );
CREATE TABLE schema_info (
                    version INTEGER NOT NULL
                );
CREATE TABLE source_health (
                    run_id TEXT NOT NULL REFERENCES runs(run_id),
                    asset_id TEXT NOT NULL,
                    source TEXT NOT NULL,
                    status TEXT NOT NULL,
                    checked_at TEXT NOT NULL,
                    message TEXT NOT NULL,
                    freshness_at TEXT,
                    PRIMARY KEY(run_id, asset_id, source)
                );
CREATE INDEX events_asset_cve ON events(asset_id, cve_id, occurred_at);
DELETE FROM "sqlite_sequence";
COMMIT;
